import random

GROUP = "sequence"
SKILL = "counting"


def count_valid_divisor_sums(target, min_sum, max_sum):
    if target < min_sum:
        return 0

    count = 0

    for current_sum in range(min_sum, max_sum + 1):
        if current_sum <= target:
            remaining_target = target - current_sum
            valid_subsums = count_valid_divisor_sums(remaining_target, min_sum, current_sum - 1)

            if valid_subsums != -1:
                count += 1

    return count


def generate(seed):
    rng = random.Random(seed)

    min_sum = rng.randint(5, 20)
    max_sum = rng.randint(30, 50)
    target = rng.randint(30, 60)

    answer = count_valid_divisor_sums(target, min_sum, max_sum)

    check = 0
    for current_sum in range(min_sum, max_sum + 1):
        if current_sum <= target:
            remaining = target - current_sum
            subsums = count_valid_divisor_sums(remaining, min_sum, current_sum - 1)
            if subsums != -1:
                check += 1

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Given a set of integers with possible divisor sums ranging from {min_sum} to {max_sum} (inclusive), find the number of distinct valid divisor sums that can be formed such that their total sum is exactly {target}. Each valid divisor sum must be within the range [{min_sum}, {max_sum}]. State only the integer."
    )
    return problem, str(answer)

