def count_subsets(n, k):
    subsets = [0] * (k + 1)
    subsets[0] = 1

    for i in range(1, n + 1):
        for j in range(min(i, k), 0, -1):
            subsets[j] += subsets[j - 1]

    return subsets[k]

def generate(seed):
    rng = random.Random(seed)

    n = rng.randint(5, 15)
    k_max = n - 1  # Ensure k is within the valid range

    # Find the smallest k where a subset of k elements can be formed with all elements summing to exactly k
    for k in range(2, k_max + 1):
        if count_subsets(n, k) > 0:
            answer = k
            break

    # Independent route: Iterate from the minimum k to find the smallest k that can form a valid subset.
    check = 2
    while True:
        if count_subsets(n, check) > 0:
            break
        check += 1

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Determine the smallest size of subsets to be chosen from a set of {n} elements such that a subset of {answer} elements can be formed where each element is unique and all elements sum to exactly {answer}. State only the integer."
    )
    return problem, str(answer)

