                while remaining_target >= min_divisor_sum:
                    remaining_target -= divisor_sum
                    count += 1
                if remaining_target < 0:
                    break
        return count


    answer = find_max_divisors(target_value, min_divisor_sum, max_divisor_sum)

    check = check_solution(target_value, min_divisor_sum, max_divisor_sum)

