def verify_count(max_degree, min_degree):
    # Independent route: Use the properties of the polynomial terms to verify the count
    # We can use the fact that the number of ways to form a term of degree d is given by the number of partitions of d into parts between min_degree and d
    valid_count = 0
    for d in range(min_degree, max_degree + 1):
        if count_terms(d, min_degree, d) > 0:
