    min_degree = rng.randint(2, 5)
    max_degree = rng.randint(10, 20)

    # Find the maximum degree where a set of terms can be formed within the given range
    for i in range(max_degree, min_degree - 1, -1):
        if count_terms(i, min_degree, i) > 0:
            max_degree_candidate = i
            break

    # Verify the count using an independent route
    valid_count = verify_count(max_degree_candidate, min_degree)
    assert valid_count == 1, f"valid_count={valid_count} expected 1"

    problem = (
