@lru_cache(maxsize=None)
def count_rectangles(m, n, min_area, max_area):
    rectangles = [0] * (max_area + 1)
    rectangles[0] = 1

    for k in range(min_area, max_area + 1):
        for i in range(m, k // min(m, n) + 1):
            for j in range(n, k // min(m, n) + 1):
                if i * j <= k:
                    rectangles[k] += rectangles[k - (i * j)]

    return rectangles[max_area]

def generate(seed):
    rng = random.Random(seed)

    m = rng.randint(2, 5)
    n = rng.randint(2, 5)
    min_area = rng.randint(m * n, 10 * m * n)
    max_area = rng.randint(min_area, 20 * m * n)

    # Independent route: calculate the threshold count of rectangles by summing areas directly.
    # This method counts the number of valid combinations where each rectangle has an area between min_area and max_area.
    total_count = 0
    for k in range(min_area, max_area + 1):
        if count_rectangles(m, n, min_area, k) > 0:
            total_count += count_rectangles(m, n, min_area, k)

    # Ensure the threshold count is within the range
    threshold_count = min(total_count, max_area)

    # Check if the threshold count is within the range of possible areas
    if threshold_count < min_area:
        threshold_count = min_area

    assert threshold_count == total_count, f"threshold_count={threshold_count} total_count={total_count}"

