def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(10, 20)

    # Generate a random set of points in a 2D plane
    points = [(rng.randint(0, 100), rng.randint(0, 100)) for _ in range(n)]

    # Count the number of collinear triplets (points that lie on the same line)
    def is_collinear(p1, p2, p3):
        (x1, y1), (x2, y2), (x3, y3) = p1, p2, p3
        return (y2 - y1) * (x3 - x1) == (y3 - y1) * (x2 - x1)

    answer = sum(1 for i in range(n) for j in range(i + 1, n) for k in range(j + 1, n) if is_collinear(points[i], points[j], points[k]))

    # Independent route: Verify the count by explicitly checking each triplet for collinearity.
    check = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if is_collinear(points[i], points[j], points[k]):
                    check += 1
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider the set of {n} points in a 2D plane: {points}. Prove that the number of triplets (p1, p2, p3) "
        f"that are collinear is exactly {answer}. Hint: Assume the opposite and show a contradiction.\n"
        f"The problem asks for the count of collinear triplets among the given points.\n"
        f"Points in the set are: {points}"
    )

    return problem, str(answer)

