def count_complementary_sums(grid_size, min_area_sum, max_area_sum, complement_target):
    dp = [0] * (complement_target + 1)
    dp[0] = 1

    for area_sum in range(min_area_sum, max_area_sum + 1):
        for j in range(complement_target, area_sum - 1, -1):
            dp[j] = max(dp[j], dp[j - area_sum] + 1)

    for j in range(complement_target, 0, -1):
        if dp[j] != 0:
            return dp[j]

    return -1


def generate(seed):
    rng = random.Random(seed)

    grid_size = rng.randint(10, 20)
    min_area_sum = rng.randint(10, 30)
    max_area_sum = rng.randint(50, 80)
    target_area = rng.randint(60, 120)

    answer = count_complementary_sums(grid_size, min_area_sum, max_area_sum, max_area_sum * (max_area_sum + 1) // 2 - target_area)

    check = -1
    total_max_sum = max_area_sum * (max_area_sum + 1) // 2
    complement_target = total_max_sum - target_area
    for area_sum in range(min_area_sum, max_area_sum + 1):
        if area_sum <= complement_target:
