def count_points_in_hypercube(n, k):
    # Calculate the total number of points in a k-dimensional hypercube of size n.
    total = n ** k
    # Calculate the points on each k-1 dimensional face (excluding the highest dimension).
    # We use a loop here to handle arbitrary dimension, but for simplicity, let's assume k=2 (rectangle) as per original logic.
    if k == 2:
