    else:
        # For k > 2, we need to subtract the points on the (k-1)-faces.
        # Here we assume the function is designed to handle higher dimensions but we keep the logic minimal.
        for i in range(2, k):
            total -= 2 * n ** i + 2 * n ** (i-1) - 1 if n == n else 0
    return total

