    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    check = sum(1 for num in numbers if is_prime(num))
    assert answer == check, f"answer={answer} check={check}"

