def find_max_terms(target, min_terms, max_terms):
    if target == 0:
        return 0

    if target < min_terms:
        return -1

    # Use dynamic programming to count the maximum number of terms
    dp = [-1] * (target + 1)
    dp[0] = 0

    for terms in range(min_terms, max_terms + 1):
