            if sum(combination) == target_sum:
                check = max(check, len(combination))

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a sequence of integers ranging from {min_terms} to {max_terms} (inclusive). "
        f"What is the maximum number of distinct terms that can be selected such that their sum is exactly {target_sum}? State only the integer."
    )
    return problem, str(answer)

import random

GROUP = "sequence"
SKILL = "induction"


def max_sequence_lengths(seq_length, min_sum, max_sum, target_sum):
    if target_sum == 0:
        return 0

    if target_sum < min_sum:
        return -1

    max_count = 0

    for seq_sum in range(min_sum, max_sum + 1):
        if seq_sum <= target_sum:
            remaining_sum = target_sum - seq_sum
            count = max_sequence_lengths(seq_length, min_sum, seq_sum - 1, remaining_sum)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    seq_length = rng.randint(5, 15)
    min_sum = rng.randint(10, 25)
    max_sum = rng.randint(40, 60)
    target_sum = rng.randint(50, 90)

    answer = max_sequence_lengths(seq_length, min_sum, max_sum, target_sum)

    check = -1
    for seq_sum in range(min_sum, max_sum + 1):
        if seq_sum <= target_sum:
            remaining_sum = target_sum - seq_sum
            count = max_sequence_lengths(seq_length, min_sum, seq_sum - 1, remaining_sum)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a sequence of length {seq_length}. Select subsequences such that the sum of their lengths ranges from {min_sum} to {max_sum} (inclusive). "
        f"What is the maximum number of distinct subsequences that can be selected such that no subset sum exceeds the target sum {target_sum} and all subset sums sum to exactly {target_sum}? State only the integer."
    )
    return problem, str(answer)
